// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";

contract MilestoneEscrow is Ownable {
    struct Milestone {
        address creator;
        uint256 totalAmount;
        uint8 milestoneCount;
        uint8 releasedCount;
        mapping(uint8=>bool) released;
        bool emergencyRefunded;
    }

    event MilestoneLocked(bytes32 indexed projectId, uint256 amount, uint8 milestoneCount, uint256 timestamp);
    event MilestoneReleased(bytes32 indexed projectId, uint256 amount, uint8 milestone, uint256 timestamp);
    event EmergencyRefund(bytes32 indexed projectId, uint256 amount, uint256 timestamp);

    mapping(bytes32=>Milestone) public milestones;
    mapping(bytes32=>bool) public projectExists;

    constructor(address initialOwner) Ownable(initialOwner) {}

    function lockMilestone(bytes32 projectId, uint8 milestoneCount) external payable {
        require(msg.value>0);
        require(milestoneCount>0);
        require(!projectExists[projectId]);

        Milestone storage ms = milestones[projectId];
        ms.creator=msg.sender;
        ms.totalAmount=msg.value;
        ms.milestoneCount=milestoneCount;
        ms.releasedCount=0;
        ms.emergencyRefunded=false;
        projectExists[projectId]=true;

        emit MilestoneLocked(projectId, msg.value, milestoneCount, block.timestamp);
    }

    function releaseMilestone(bytes32 projectId, uint8 milestone) external onlyOwnerOrCreator(projectId) {
        require(projectExists[projectId]);
        require(!milestones[projectId].emergencyRefunded);
        require(milestone>0&&milestone<=milestones[projectId].milestoneCount);
        require(!milestones[projectId].released[milestone]);

        Milestone storage ms = milestones[projectId];
        uint256 amount = ms.totalAmount/ms.milestoneCount;
        if (milestone==ms.milestoneCount) amount = ms.totalAmount - (amount*(ms.milestoneCount-1));

        ms.released[milestone]=true;
        ms.releasedCount++;

        (bool ok,) = payable(ms.creator).call{value:amount}("");
        require(ok);
        emit MilestoneReleased(projectId, amount, milestone, block.timestamp);
    }

    function emergencyRefund(bytes32 projectId) external onlyOwnerOrCreator(projectId) {
        require(projectExists[projectId]);
        require(!milestones[projectId].emergencyRefunded);

        Milestone storage ms = milestones[projectId];
        uint256 refund = ms.totalAmount;
        uint256 released = (ms.totalAmount/ms.milestoneCount)*ms.releasedCount;
        if (released<refund) refund-=released;
        else refund=0;
        require(refund>0);

        ms.emergencyRefunded=true;
        (bool ok,) = payable(ms.creator).call{value:refund}("");
        require(ok);
        emit EmergencyRefund(projectId, refund, block.timestamp);
    }

    function getMilestoneInfo(bytes32 projectId) external view returns (address,uint256,uint8,uint8,bool) {
        require(projectExists[projectId]);
        Milestone storage ms=milestones[projectId];
        return (ms.creator,ms.totalAmount,ms.milestoneCount,ms.releasedCount,ms.emergencyRefunded);
    }

    function isReleased(bytes32 projectId, uint8 milestone) external view returns (bool) {
        require(projectExists[projectId]);
        return milestones[projectId].released[milestone];
    }

    modifier onlyOwnerOrCreator(bytes32 projectId) {
        require(msg.sender==owner() || (projectExists[projectId]&&msg.sender==milestones[projectId].creator));
        _;
    }

    receive() external payable { revert("Use lockMilestone()"); }
}
